def handle(app, svc):
    # Submit the application to the partner service (API v2).
    resp = svc.apply(app) or {}
    result = resp.get("result") or {}
    outcome = result.get("outcome")
    limit = result.get("credit_limit")

    # Normalize limit to a non-negative int.
    try:
        limit = int(limit)
    except (TypeError, ValueError):
        limit = 0
    if limit < 0:
        limit = 0

    # Network referral rule: a self_employed applicant with requested_limit
    # strictly above 6000 must be sent to manual review instead of being
    # issued. A decline stays a decline (rule only overrides "issue").
    requested = app.get("requested_limit")
    try:
        requested = int(requested)
    except (TypeError, ValueError):
        requested = None
    employment = app.get("employment")

    def is_self_employed_over_limit():
        return (
            employment == "self_employed"
            and requested is not None
            and requested > 6000
        )

    if outcome == "approved":
        if is_self_employed_over_limit():
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": limit}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    elif outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}
    else:
        # Unknown/missing outcome: safe default is manual review.
        return {"action": "queue_review", "limit": 0}

